DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[ProductListPriceHistory]([ProductID],[StartDate],[EndDate],[ListPrice],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[StartDate],S.[EndDate],S.[ListPrice],S.[ModifiedDate],@B FROM ssis_flow.Delta_ProductListPriceHistory S;
INSERT stg.[ProductListPriceHistory]([ProductID],[StartDate],[EndDate],[ListPrice],[ModifiedDate],LoadBatchID) SELECT [ProductID],[StartDate],[EndDate],[ListPrice],[ModifiedDate],@B FROM etl_raw.[ProductListPriceHistory];
INSERT etl_v2.SourceChange SELECT @B,N'Production.ProductListPriceHistory','I',@Next,(SELECT R.[ProductID],R.[StartDate] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[ProductListPriceHistory] R;
END ELSE BEGIN
SELECT [ProductID],[StartDate],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_ProductListPriceHistory FROM ssis_flow.Delta_ProductListPriceHistory;
INSERT etl_v2.SourceChange SELECT @B,N'Production.ProductListPriceHistory',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[ProductID],C.[StartDate] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_ProductListPriceHistory C LEFT JOIN etl_raw.[ProductListPriceHistory] R ON R.[ProductID]=C.[ProductID] AND R.[StartDate]=C.[StartDate];
DELETE R FROM etl_raw.[ProductListPriceHistory] R JOIN #CT_ProductListPriceHistory C ON R.[ProductID]=C.[ProductID] AND R.[StartDate]=C.[StartDate] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[EndDate]=S.[EndDate],R.[ListPrice]=S.[ListPrice],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[ProductListPriceHistory] R JOIN #CT_ProductListPriceHistory C ON R.[ProductID]=C.[ProductID] AND R.[StartDate]=C.[StartDate] JOIN ssis_flow.Delta_ProductListPriceHistory S ON S.[ProductID]=C.[ProductID] AND S.[StartDate]=C.[StartDate] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[ProductListPriceHistory]([ProductID],[StartDate],[EndDate],[ListPrice],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[StartDate],S.[EndDate],S.[ListPrice],S.[ModifiedDate],@B FROM #CT_ProductListPriceHistory C JOIN ssis_flow.Delta_ProductListPriceHistory S ON S.[ProductID]=C.[ProductID] AND S.[StartDate]=C.[StartDate] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[ProductListPriceHistory] R WHERE R.[ProductID]=S.[ProductID] AND R.[StartDate]=S.[StartDate]);
INSERT stg.[ProductListPriceHistory]([ProductID],[StartDate],[EndDate],[ListPrice],[ModifiedDate],LoadBatchID) SELECT R.[ProductID],R.[StartDate],R.[EndDate],R.[ListPrice],R.[ModifiedDate],@B FROM etl_raw.[ProductListPriceHistory] R JOIN #CT_ProductListPriceHistory C ON R.[ProductID]=C.[ProductID] AND R.[StartDate]=C.[StartDate] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;